-- ==============================================================================
-- SIGA-AP: ESQUEMA COMPLETO Y PERSISTENTE PARA SUPABASE (POSTGRESQL)
-- Centro de Formación Técnica (CFT) - Gestión Integral de Capacitaciones y Actividades
-- ==============================================================================
-- Instrucciones:
-- 1. Abrí tu consola de Supabase (https://supabase.com/dashboard).
-- 2. Seleccioná tu proyecto y andá a "SQL Editor" en el menú lateral.
-- 3. Pegá todo el contenido de este archivo y presioná "Run" (Ejecutar).
-- 4. Copiá tu Project URL y Anon Key desde Project Settings -> API.
-- ==============================================================================

-- Habilitar extensiones necesarias
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- ==============================================================================
-- 1. TABLA: profiles (Usuarios y accesos al sistema)
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.profiles (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario TEXT NOT NULL UNIQUE,
    clave TEXT NOT NULL,
    nombre TEXT,
    email TEXT,
    rol TEXT DEFAULT 'Operador',
    estado TEXT DEFAULT 'Activo',
    creado_el TIMESTAMPTZ DEFAULT NOW(),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- 2. TABLA: programas (Catálogo de programas de capacitación)
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.programas (
    codigo_programa TEXT PRIMARY KEY,
    nombre TEXT NOT NULL,
    descripcion TEXT DEFAULT '',
    estado TEXT DEFAULT 'Activo',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- 3. TABLA: cursos (Catálogo de cursos técnicos)
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.cursos (
    codigo_curso TEXT PRIMARY KEY,
    nombre TEXT NOT NULL,
    hs_teoria NUMERIC DEFAULT 0,
    hs_practica NUMERIC DEFAULT 0,
    hs_totales NUMERIC DEFAULT 0,
    modalidad TEXT DEFAULT 'Presencial',
    estado TEXT DEFAULT 'Activo',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- 4. TABLA: instructores (Catálogo de docentes e instructores)
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.instructores (
    codigo_instructor TEXT PRIMARY KEY,
    nombre TEXT NOT NULL,
    apellido TEXT NOT NULL,
    dni TEXT,
    email TEXT,
    especialidad TEXT,
    tipo TEXT DEFAULT 'Interno',
    estado TEXT DEFAULT 'Activo',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- 5. TABLA: dotacion (Padrón maestro de empleados de RRHH)
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.dotacion (
    legajo TEXT PRIMARY KEY,
    apellido TEXT NOT NULL,
    nombre TEXT NOT NULL,
    puesto TEXT,
    categoria TEXT,
    direccion TEXT,
    gerencia TEXT,
    jefatura TEXT,
    coordinacion TEXT DEFAULT '',
    email TEXT,
    estado TEXT DEFAULT 'Activo',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- 6. TABLA: proveedores (Proveedores y Entes Calificadores con Seguimiento)
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.proveedores (
    codigo_proveedor TEXT PRIMARY KEY,
    razon_social TEXT NOT NULL,
    ente TEXT,
    rubro TEXT,
    contacto TEXT,
    telefono TEXT,
    email TEXT,
    estado TEXT DEFAULT 'Activo',
    carpetas_seguimiento JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- 7. TABLA: capacitaciones (Actividades y Clases Multi-clase)
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.capacitaciones (
    id_cap TEXT PRIMARY KEY,
    programa TEXT,
    nombre_curso TEXT,
    estado TEXT DEFAULT 'Programado',
    tema TEXT DEFAULT '',
    fecha TEXT,
    hs_inicio TEXT,
    hs_fin TEXT,
    lugar TEXT,
    centro TEXT,
    instructor_1 TEXT,
    instructor_2 TEXT,
    observaciones TEXT DEFAULT '',
    clase_nro INTEGER DEFAULT 1,
    total_clases TEXT DEFAULT '1',
    fecha_eval_transferencia TEXT,
    estado_transferencia TEXT DEFAULT 'Pendiente',
    fecha_envio_transferencia TEXT,
    fecha_tra TEXT,
    estado_tra TEXT DEFAULT 'Pendiente',
    estado_sat TEXT DEFAULT 'Pendiente',
    estado_encuesta TEXT DEFAULT 'Pendiente',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- 8. TABLA: asistentes (Nómina de presentes por capacitación)
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.asistentes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_cap TEXT NOT NULL REFERENCES public.capacitaciones(id_cap) ON DELETE CASCADE,
    legajo TEXT,
    apellido TEXT,
    nombre TEXT,
    puesto TEXT,
    categoria TEXT,
    direccion TEXT,
    gerencia TEXT,
    jefatura TEXT,
    email TEXT,
    calificacion TEXT DEFAULT '',
    observaciones TEXT DEFAULT '',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- 9. TABLA: evaluaciones_satisfaccion (Encuestas de satisfacción por QR/Link)
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.evaluaciones_satisfaccion (
    id TEXT PRIMARY KEY,
    id_cap TEXT REFERENCES public.capacitaciones(id_cap) ON DELETE SET NULL,
    instructor TEXT,
    puntaje_objetivos NUMERIC,
    puntaje_aplicabilidad NUMERIC,
    puntaje_instructor NUMERIC,
    puntaje_material NUMERIC,
    puntaje_entorno NUMERIC,
    puntaje_general NUMERIC,
    puntaje_docente NUMERIC,
    puntaje_contenido NUMERIC,
    destacados TEXT,
    sugerencias TEXT,
    comentarios TEXT,
    fecha_registro TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- 10. TABLA: transferencias (Evaluaciones de impacto y transferencia al puesto)
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.transferencias (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_cap TEXT REFERENCES public.capacitaciones(id_cap) ON DELETE CASCADE,
    jefatura TEXT,
    nombre_curso TEXT,
    fecha_curso TEXT,
    legajo TEXT,
    nombre TEXT,
    aplica_contenidos TEXT,
    motivo_dificultad TEXT,
    plan_accion TEXT,
    firma_responsable TEXT,
    fecha_registro TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- 11. TABLA: certificaciones_externas (Ensayos END, Soldadores e Izaje)
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.certificaciones_externas (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo TEXT NOT NULL,
    alcance TEXT,
    categoria TEXT,
    subcategoria TEXT,
    legajo INTEGER,
    apellido_nombre TEXT,
    puesto TEXT,
    area_jefatura TEXT,
    proveedor_id TEXT,
    proveedor_ente TEXT,
    fecha_emision TEXT,
    fecha_vencimiento TEXT,
    tiene_vencimiento BOOLEAN DEFAULT TRUE,
    archivo_pdf_nombre TEXT,
    observaciones TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- VISTAS DE COMPATIBILIDAD (Para soportar endpoints duales)
-- ==============================================================================
CREATE OR REPLACE VIEW public.evaluaciones AS 
    SELECT * FROM public.evaluaciones_satisfaccion;

CREATE OR REPLACE VIEW public.encuestas_transferencia AS 
    SELECT * FROM public.transferencias;

-- ==============================================================================
-- ÍNDICES DE ALTO RENDIMIENTO
-- ==============================================================================
CREATE INDEX IF NOT EXISTS idx_asistentes_id_cap ON public.asistentes(id_cap);
CREATE INDEX IF NOT EXISTS idx_asistentes_legajo ON public.asistentes(legajo);
CREATE INDEX IF NOT EXISTS idx_capacitaciones_fecha ON public.capacitaciones(fecha);
CREATE INDEX IF NOT EXISTS idx_capacitaciones_estado ON public.capacitaciones(estado);
CREATE INDEX IF NOT EXISTS idx_eval_sat_id_cap ON public.evaluaciones_satisfaccion(id_cap);
CREATE INDEX IF NOT EXISTS idx_transf_id_cap ON public.transferencias(id_cap);
CREATE INDEX IF NOT EXISTS idx_certif_legajo ON public.certificaciones_externas(legajo);
CREATE INDEX IF NOT EXISTS idx_certif_codigo ON public.certificaciones_externas(codigo);

-- ==============================================================================
-- SEGURIDAD ROW LEVEL SECURITY (RLS) Y POLÍTICAS DE ACCESO PÚBLICO
-- ==============================================================================
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.programas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cursos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.instructores ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.dotacion ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.proveedores ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.capacitaciones ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.asistentes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.evaluaciones_satisfaccion ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transferencias ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.certificaciones_externas ENABLE ROW LEVEL SECURITY;

DO $$ 
DECLARE
    t TEXT;
    tablas TEXT[] := ARRAY[
        'profiles', 'programas', 'cursos', 'instructores', 
        'dotacion', 'proveedores', 'capacitaciones', 'asistentes', 
        'evaluaciones_satisfaccion', 'transferencias', 'certificaciones_externas'
    ];
BEGIN
    FOREACH t IN ARRAY tablas LOOP
        EXECUTE format('DROP POLICY IF EXISTS "Permitir acceso publico total a %I" ON public.%I', t, t);
        EXECUTE format('CREATE POLICY "Permitir acceso publico total a %I" ON public.%I FOR ALL TO anon, authenticated USING (true) WITH CHECK (true)', t, t);
    END LOOP;
END $$;

